import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import {execFileSync} from 'node:child_process';import {hash,json} from './seal-simple-website-successor.mjs';
const stage='F:/VisibleMedicine/staging/20261024-practice-actions',root=stage+'/atlas',prep=json(stage+'/PREPARED.json'),commit=json(stage+'/COMMIT-v3.json');
const git=(at,...args)=>execFileSync('git',['-C',at,...args],{encoding:'utf8',windowsHide:true,stdio:'pipe',maxBuffer:32e6}).trim();
assert.equal(git(root,'rev-parse','HEAD'),commit.head);assert.equal(git(root,'rev-parse','HEAD^{tree}'),commit.tree);assert.equal(git(root,'status','--porcelain'),'');assert.equal(git(prep.parent,'rev-parse','HEAD'),prep.head);assert.equal(git(prep.parent,'status','--porcelain'),'');
const phases=['renderer-v4','reviews-v4','display-v4','feature-v4','rendererScope-v4','types-v4','requirements-v3','requirementsCheck-v5','panelNavigation-v4','resultNavigation-v4','returnView-v4','practice-v4','nested-v5','nestedComponent-v4','nestedReview-v4','holds-v4','geometry-v4','snapshot-v4','build-v3','rendererCheck-v3','requirementsCheck-v6','regional-v3','exportRegional-v3'];
for(const phase of phases){const dir=stage+'/checks/'+phase,t=json(dir+'/TERMINAL.json');assert.equal(t.code,0,phase);for(const stream of ['stdout','stderr'])assert.equal(hash(dir+'/'+stream+'.log'),t[stream+'Sha256']);for(const row of t.sourceInputs)assert.equal(hash(root+'/'+row.path),row.sha256,phase+':'+row.path);}
const types=json(stage+'/checks/types-v4/RESULT.json');assert.equal(types.roots.length,7);assert.equal(types.diagnostics.length,0);assert(types.actualStrictConfiguration&&!types.moduleSubstitutions);for(const row of types.sourceFiles)assert.equal(hash(row.path),row.sha256,row.path);
const sourceRows=git(root,'ls-files','-z').split('\0').filter(Boolean).map(p=>({path:p,bytes:fs.statSync(root+'/'+p).size,sha256:hash(root+'/'+p)}));assert.equal(sourceRows.length,6374);
const changed=new Set([...commit.authored,...commit.generated]);for(const row of prep.files){assert.equal(hash(prep.parent+'/'+row.path),row.sha256,row.path);if(!changed.has(row.path))assert.equal(hash(root+'/'+row.path),row.sha256,row.path);}
const preservation=json(stage+'/PRESERVATION-v3.json');assert(preservation.all1104WorksheetsAnd9936LessonsExact&&preservation.all232Concepts424SessionsExact);assert.equal(hash(preservation.baseline),preservation.baselineSha256);assert.equal(hash(preservation.candidate),preservation.candidateSha256);
assert.deepEqual(json(preservation.baseline).rows,json(preservation.candidate).rows);assert.deepEqual(json(preservation.baseline).concepts,json(preservation.candidate).concepts);
const manifestPath=stage+'/qa-v3/public/atlas-runtime/head-neck/manifest.json',manifest=json(manifestPath);assert.equal(manifest.sourceCommit,commit.head);assert.equal(manifest.patientDataIncluded,false);assert.equal(manifest.clinicalApproved,false);for(const row of manifest.files)assert.equal(hash(path.dirname(manifestPath)+'/'+row.path),row.sha256,row.path);
const start=json(stage+'/browser-v3/STARTED.json'),browser=json(stage+'/browser-v3/RESULT.json'),terminal=json(stage+'/browser-v3/TERMINAL.json');
assert.equal(start.sourceCommit,commit.head);assert.equal(start.manifestSha256,hash(manifestPath));assert.equal(browser.sourceCommit,commit.head);assert.equal(browser.ownedTabClosed,true);assert.equal(terminal.code,0);assert(terminal.graceful);assert.equal(start.pid,terminal.pid);
assert(browser.desktop.sourcesExpanded&&browser.desktop.nextButtonVisible&&browser.desktop.footerMeetsPanelEdge);assert(browser.compact.footerMeetsPanelEdge&&browser.compact.nextButtonVisible);assert(browser.completion.retryVisible&&browser.completion.dismissVisible);assert.equal(browser.ownerTabsChanged,false);
const buildFiles=[];function walk(at,prefix,rows){for(const row of fs.readdirSync(at,{withFileTypes:true})){assert(!row.isSymbolicLink());const p=prefix+row.name;if(row.isDirectory())walk(at+'/'+row.name,p+'/',rows);else rows.push({path:p,bytes:fs.statSync(at+'/'+row.name).size,sha256:hash(at+'/'+row.name)});}}
walk(root+'/dist','',buildFiles);assert(buildFiles.length>500);fs.writeFileSync(stage+'/BUILD_ARTIFACTS.json',JSON.stringify({at:new Date().toISOString(),sourceCommit:commit.head,files:buildFiles},null,2)+'\n',{flag:'wx'});
const evidence=[];for(const name of ['PREPARED.json','COMMIT.json','COMMIT-v2.json','COMMIT-v3.json','PRESERVATION.json','PRESERVATION-v2.json','PRESERVATION-v3.json','SOURCE_DIFF.patch','SOURCE_DIFF-v2.patch','SOURCE_DIFF-v3.patch','LOCAL_TEST_DEPENDENCIES.json','candidate-snapshot.json','candidate-snapshot-v2.json','candidate-snapshot-v3.json','candidate-snapshot-v4.json','BUILD_ARTIFACTS.json'])evidence.push({path:name,sha256:hash(stage+'/'+name)});
walk(stage+'/checks','checks/',evidence);walk(stage+'/browser','browser/',evidence);walk(stage+'/browser-v2','browser-v2/',evidence);walk(stage+'/browser-v3','browser-v3/',evidence);
const value={at:new Date().toISOString(),atlas:root,atlasHead:commit.head,atlasTree:commit.tree,parentHead:prep.head,intermediateHeads:[json(stage+'/COMMIT.json').head,json(stage+'/COMMIT-v2.json').head],sourceRows,sourcePaths:sourceRows.length,authored:commit.authored,generated:commit.generated,evidence,featureCases:7,typeRoots:7,typeActualGraphFiles:types.sourceFiles.length,typeDiagnostics:0,fullProjectTypes:false,nativeProductionBuildPassed:true,buildFiles:buildFiles.length,exportedRootBrowserVerified:true,browserResult:stage+'/browser-v3/RESULT.json',browserResultSha256:hash(stage+'/browser-v3/RESULT.json'),preservation:stage+'/PRESERVATION-v3.json',preservationSha256:hash(stage+'/PRESERVATION-v3.json'),all1104Worksheets9936Lessons232Concepts424TargetsExact:true,shoulderDisplayRevisionsAdvanced:9,allGeometryLicensingAndDependenciesUnchanged:true,websiteIntegrationPending:true,previewChanged:false,installed:false,publicDeployment:false,clinicalApproval:false,patientSpaceRegistration:false,wholeSuitePassing:false,authenticatedAcceptance:false};
fs.writeFileSync(stage+'/SOURCE_BOUND.json',JSON.stringify(value,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({sourceReceipt:stage+'/SOURCE_BOUND.json',sha256:hash(stage+'/SOURCE_BOUND.json'),sourceCommit:commit.head,sourcePaths:sourceRows.length,buildFiles:buildFiles.length,typeFiles:types.sourceFiles.length,previewChanged:false}));
